output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves flank both sides of the shopper.",
    "abstraction": {
      "state_properties": {
        "shelves_on_both_sides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            "shelves_on_both_sides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_single_file_aisle",
    "text": "A shopper must not move into a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "shelves_on_both_sides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            "shelves_on_both_sides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enter_single_file_aisle_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_aisle_with_cart"
    }
  },
  {
    "id": "cart_drop_only_at_aisle_mouths",
    "text": "Carts may only be put down at designated wide aisle mouths before entering the narrow shelf aisles.",
    "abstraction": {
      "state_properties": {
        "wide_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "drop_cart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "drop_cart",
          {
            "not": "wide_aisle_mouth"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "After parking a cart at an aisle mouth, the shopper is obliged to retrieve a cart before leaving the store.",
    "abstraction": {
      "state_properties": {
        "wide_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "drop_cart_at_aisle_mouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "wide_aisle_mouth"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickup_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "drop_cart_at_aisle_mouth",
      "discharge": "pickup_cart"
    }
  },
  {
    "id": "no_hand_carrying_in_open_store",
    "text": "Except at the entrance/cart bay and within the narrow hand-carry aisles, shoppers should not roam the store without their cart.",
    "abstraction": {
      "state_properties": {
        "entrance_or_cart_bay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "wide_aisle_mouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "shelves_on_both_sides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            "shelves_on_both_sides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "hand_carry_zone": {
          "or": [
            "wide_aisle_mouth",
            "single_file_shelf_aisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": {
              "or": [
                "entrance_or_cart_bay",
                "hand_carry_zone"
              ]
            }
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_shelf_interaction",
    "text": "Items on open, cart-accessible shelf faces may not be taken unless the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "shelves_on_both_sides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            "shelves_on_both_sides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cart_accessible_shelf_face": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_shelf_aisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "cart_accessible_shelf_face",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_cart_circulation",
    "text": "When pushing a cart, shoppers must follow the one-way circulation and may not move westward.",
    "abstraction": {
      "state_properties": {
        "cart_traffic": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_traffic",
          "W"
        ]
      }
    }
  },
  {
    "id": "exit_after_cart_shelf_pickup",
    "text": "After interacting with any cart-accessible shelf face, the shopper is obliged to proceed eventually to the exit.",
    "abstraction": {
      "state_properties": {
        "shelves_on_both_sides": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            "shelves_on_both_sides",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cart_accessible_shelf_face": {
          "and": [
            "adjShelf",
            {
              "not": "single_file_shelf_aisle"
            }
          ]
        }
      },
      "events": {
        "cart_shelf_pickup": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "cart_accessible_shelf_face"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_shelf_pickup",
      "discharge": "EXIT"
    }
  }
]
